import{_ as e,o as t,c as o,aa as n}from"./chunks/framework.BAs_AphD.js";const r="/buildary-help-preview/media/cs/diary/editace_domeny.png",i="/buildary-help-preview/media/cs/diary/faktury_domeny.png",h=JSON.parse('{"title":"Placený režim a fakturace","description":"","frontmatter":{"title":"Placený režim a fakturace","wiki":"cs:firstofall:payment"},"headers":[],"relativePath":"firstofall/payment.md","filePath":"firstofall/payment.md","lastUpdated":1794209661000}'),d={name:"firstofall/payment.md"};function l(s,a,u,p,m,c){return t(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="placeny-rezim-a-fakturace" tabindex="-1">Placený režim a fakturace <a class="header-anchor" href="#placeny-rezim-a-fakturace" aria-label="Permalink to &quot;Placený režim a fakturace&quot;">​</a></h1><p>Buildary si nejdřív měsíc zdarma vyzkoušíte. Pak doménu převedete do placeného režimu a platíte čtvrtletně za každou aktivní stavbu podle počtu uživatelů a zapnutých modulů.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/fakturace">Přejít na placený režim a vyřešit fakturaci</a> v Akademii.</p><h2 id="rezimy-domeny" tabindex="-1">Režimy domény <a class="header-anchor" href="#rezimy-domeny" aria-label="Permalink to &quot;Režimy domény&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Režim</th><th>Co platí</th></tr></thead><tbody><tr><td><strong>Zkušební</strong></td><td>30 dní zdarma v plném rozsahu. Nic se nefakturuje.</td></tr><tr><td><strong>Standardní</strong> (placený)</td><td>Fakturace podle pravidel na této stránce.</td></tr><tr><td><strong>Individuální</strong></td><td>Podmínky podle individuální smlouvy. Do tohoto režimu doménu přepneme my – pokud o něj máte zájem, napište na <a href="mailto:buildary@firstis.eu" target="_blank" rel="noreferrer">buildary@firstis.eu</a>.</td></tr></tbody></table><p>Do placeného režimu se převádí <strong>doména</strong>, ve které jsou (nebo budou) vaše stavby. Máte-li firemní doménu, stačí převést ji – osobní doménu převádět nemusíte, pokud v ní nezakládáte stavby. Viz <a href="/buildary-help-preview/firstofall/domain">Firemní doména</a>.</p><h2 id="prejit-do-placeneho-rezimu" tabindex="-1">Přejít do placeného režimu <a class="header-anchor" href="#prejit-do-placeneho-rezimu" aria-label="Permalink to &quot;Přejít do placeného režimu&quot;">​</a></h2><p>Ke konci zkušební doby vás na to aplikace upozorní a přechod sama nabídne. Kdykoli dřív to uděláte takto:</p><ol><li>V levém panelu klikněte na ikonu glóbu a v Seznamu domén otevřete doménu ikonou tužky.</li><li>Vyplňte všechny fakturační údaje včetně <strong>kontaktu pro fakturaci</strong> – na tyto e-maily budou chodit výzvy k platbě a faktury.</li><li>Klikněte na <strong>Přejdi do placeného režimu</strong>.</li><li>Stránku <strong>uložte</strong> tlačítkem vpravo dole.</li></ol><figure class="shot" style="--w:640px;"><img src="'+r+'" alt="Úprava domény s tlačítkem Přejdi do placeného režimu" loading="lazy"></figure><div class="info custom-block"><p class="custom-block-title">Když placený režim nechcete</p><p>Nemusíte dělat nic. Dál můžete pracovat na stavbách, kam vás přizval někdo jiný a kde platí on – jen ne na vlastních stavbách. Rozhodnutí můžete změnit v doméně ještě do 3 měsíců.</p></div><h2 id="jak-probiha-fakturace" tabindex="-1">Jak probíhá fakturace <a class="header-anchor" href="#jak-probiha-fakturace" aria-label="Permalink to &quot;Jak probíhá fakturace&quot;">​</a></h2><ul><li>Fakturuje se <strong>jednou za 3 měsíce zpětně</strong>, za každou stavbu zvlášť, podle počtu uživatelů a modulů na stavbě. Ceník: <a href="http://www.buildary.online/cs/cena-cz" target="_blank" rel="noreferrer">Česko</a>, <a href="http://www.buildary.online/sk/cena" target="_blank" rel="noreferrer">Slovensko</a>.</li><li>První fakturace proběhne 3 měsíce po založení stavby nebo po přechodu do placeného režimu.</li><li>Za každou stavbu přijde <strong>Výzva k platbě</strong>. Zaplaťte ji s uvedeným variabilním symbolem.</li><li>Po spárování platby přijde <strong>Daňový doklad</strong> – konečná faktura potvrzující úhradu.</li></ul><p>Všechny doklady najdete v detailu domény na záložce <strong>Fakturace za doménu</strong>. Po rozkliknutí zaplacených nebo nezaplacených faktur stavby je máte v přílohách ke stažení.</p><figure class="shot" style="--w:600px;"><img src="'+i+'" alt="Záložka Fakturace za doménu" loading="lazy"></figure><h2 id="splatnost-a-neuhrazene-faktury" tabindex="-1">Splatnost a neuhrazené faktury <a class="header-anchor" href="#splatnost-a-neuhrazene-faktury" aria-label="Permalink to &quot;Splatnost a neuhrazené faktury&quot;">​</a></h2><p>Výzva k platbě je splatná do 1 měsíce. Když zaplacená není:</p><table tabindex="0"><thead><tr><th>Kdy</th><th>Co se stane</th></tr></thead><tbody><tr><td>Po splatnosti</td><td>Aplikace začne na neuhrazenou platbu upozorňovat. U stavby se v Seznamu staveb objeví oranžová nebo červená ikona.</td></tr><tr><td>1 měsíc po splatnosti</td><td>Přístup na stavbu se <strong>pozastaví</strong> všem uživatelům. Po úhradě se zase obnoví.</td></tr><tr><td>2 měsíce po splatnosti</td><td>Stavba se <strong>ukončí ke smazání</strong> a přijde e-mail Oznámení o ukončení projektu.</td></tr><tr><td>Do 3 měsíců od ukončení</td><td>Po úhradě se stavba vrátí do aktivního stavu.</td></tr><tr><td>Později</td><td>Stavba se <strong>nenávratně smaže</strong>.</td></tr></tbody></table><p>Dokud má doména neuhrazené faktury – i za dávno smazané stavby – nejde v ní založit novou stavbu.</p><h2 id="ukoncit-fakturaci-za-stavbu" tabindex="-1">Ukončit fakturaci za stavbu <a class="header-anchor" href="#ukoncit-fakturaci-za-stavbu" aria-label="Permalink to &quot;Ukončit fakturaci za stavbu&quot;">​</a></h2><p>Fakturují se jen aktivní stavby. Když už stavbu nepotřebujete, <a href="/buildary-help-preview/diary/projectended">ukončete ji v aplikaci</a> – tím skončí i její fakturace.</p>',21)])])}const v=e(d,[["render",l]]);export{h as __pageData,v as default};
